CREATE TABLE studios(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,slug VARCHAR(255) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,owner_user_id BINARY(16) NOT NULL,status VARCHAR(30) NOT NULL,settings TEXT,created_at TIMESTAMP(6) NOT NULL,INDEX idx_studio_tenant(tenant_id));
CREATE TABLE studio_members(id BINARY(16) PRIMARY KEY,studio_id BINARY(16) NOT NULL,user_id BINARY(16),email VARCHAR(255),role VARCHAR(255) NOT NULL,state VARCHAR(255) NOT NULL,invite_token VARCHAR(255) UNIQUE,expires_at TIMESTAMP(6),UNIQUE(studio_id,user_id),FOREIGN KEY(studio_id) REFERENCES studios(id) ON DELETE CASCADE);
CREATE TABLE studio_contacts(id BINARY(16) PRIMARY KEY,studio_id BINARY(16) NOT NULL,type VARCHAR(255) NOT NULL,value VARCHAR(255) NOT NULL,primary_contact BOOLEAN NOT NULL,FOREIGN KEY(studio_id) REFERENCES studios(id) ON DELETE CASCADE);
